  ["test","bun test lib/site.test.ts",20000],
  ["lint","bun run lint",20000],
  ["typecheck","bun run typecheck",20000]
];
const out=await Promise.all(cmds.map(async ([name,cmd,ms])=>{
  const r=await tools.exec_command({cmd,workdir:base,yield_time_ms:ms,max_output_tokens:20000});
  return {name,...r};
}));
for(const r of out){ text(`---${r.name}---\n${r.output}`); }

const base="/tmp/portfolio-avatar-pr";
const results=await Promise.all([
  tools.exec_command({cmd:"bun test",workdir:base,yield_time_ms:30000,max_output_tokens:30000}),
  tools.exec_command({cmd:"bun run build",workdir:base,yield_time_ms:30000,max_output_tokens:30000})
]);
for(const [i,r] of results.entries()){ text(`---${i===0?"full test":"build"} (exit ${r.exit_code ?? "running"})---\n${r.output}`); }

