];
const out=await Promise.all(cmds.map(async ([name,cmd,ms])=>({name,...await tools.exec_command({cmd,workdir:base,yield_time_ms:ms,max_output_tokens:30000})})));
for(const r of out){ text(`---${r.name} exit ${r.exit_code ?? "running"}---\n${r.output}`); }

